package com.astra.tvhome;
import android.content.*;import android.media.AudioManager;import android.view.KeyEvent;import java.util.*;
/** Only explicitly mapped spare colour keys are consumed. Home, Back and navigation keys retain their roles. */
final class RemoteBindings {
    final Map<Integer,Long> down=new HashMap<>();
    boolean dispatch(Context context,KeyEvent event){int code=event.getKeyCode();if(code<183||code>186)return false;android.content.SharedPreferences pref=context.getSharedPreferences("MainActivity",0);String tap=pref.getString("remote."+code+".tap","none"),hold=pref.getString("remote."+code+".hold","none");if(tap.equals("none")&&hold.equals("none"))return false;if(event.getAction()==KeyEvent.ACTION_DOWN){if(event.getRepeatCount()==0)down.put(code,event.getEventTime());return true;}if(event.getAction()==KeyEvent.ACTION_UP&&!event.isCanceled()){long started=down.containsKey(code)?down.remove(code):event.getDownTime();String action=event.getEventTime()-started>=550&&!hold.equals("none")?hold:tap;perform(context,action);}return true;}
    static void perform(Context c,String action){try{if(action.equals("none"))return;if(action.equals("mute")){((AudioManager)c.getSystemService(Context.AUDIO_SERVICE)).adjustStreamVolume(AudioManager.STREAM_MUSIC,AudioManager.ADJUST_TOGGLE_MUTE,AudioManager.FLAG_SHOW_UI);return;}Intent intent;if(action.startsWith("app:")){String pkg=action.substring(4);Maintenance.packageName(pkg);intent=c.getPackageManager().getLeanbackLaunchIntentForPackage(pkg);if(intent==null)intent=c.getPackageManager().getLaunchIntentForPackage(pkg);if(intent==null)return;}else{intent=new Intent(c,MainActivity.class);if(action.equals("inputs")||action.equals("settings")||action.equals("apps"))intent.putExtra("panel",action);else if(!action.equals("home"))return;}intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);c.startActivity(intent);}catch(Exception ignored){}}
}
